window.createLegendsUI=function(api){
'use strict';
const F=window.Frontera,$=id=>document.getElementById(id),esc=api.escape;
let generation=null,selected=null,trial=null;
function clueText(s,e,i){const q=F.legendPuzzle(s,e.id);if(e.mode==='order')return i===0?'Primero '+e.tokens[q.order[0]]+'. Después '+e.tokens[q.order[1]]+'.':'Luego '+e.tokens[q.order[2]]+'. El último sello es '+e.tokens[q.order[3]]+'.';if(e.mode==='balance')return i===0?'El primer núcleo necesita '+q.target[0]+' cargas; el segundo, '+q.target[1]+'.':'El tercer núcleo necesita '+q.target[2]+' cargas. Cada núcleo vuelve a cero después de cuatro.';return i===0?'Empieza en la esquina superior izquierda. Avanza una casilla por vez, sin pisar las runas oscuras.':'El umbral está en la esquina inferior derecha. Si un camino se cierra, busca un desvío; siempre existe un paso.';}
function location(s,id,role,clue=-1){const o=F.legendPoint(s,id,role,clue);return esc(F.MAPS[o.mapId].name)+' · '+Math.floor(o.x/32)+', '+Math.floor(o.y/32);}
function journal(){if(api.battle()||api.locked())return;generation=F.generationOfMap(api.state().mapId);renderJournal();api.openDialog('legendsDialog');}
function renderJournal(){const s=api.state(),j=F.ensureLegends(s),query=$('legendSearch').value.toLocaleLowerCase().trim();$('legendGeneration').innerHTML=Object.values(F.GENERATIONS).map(g=>'<option value="'+g.id+'">'+g.name+(s.generationJourney.unlocked[g.id]===undefined?' · frontera cerrada':'')+'</option>').join('');$('legendGeneration').value=String(generation);const all=Object.values(F.LEGENDS),list=all.filter(e=>e.generation===generation&&(!query||(e.title+' '+F.DATA[e.id].name).toLocaleLowerCase().includes(query))),caught=all.filter(e=>F.legendStatus(s,e.id).captured).length;$('legendSummary').textContent=caught+' / '+all.length+' encuentros completados · '+list.length+' leyendas en esta vista';$('legendList').innerHTML=list.map(e=>{const p=F.legendStatus(s,e.id);return'<article class="legend-card'+(p.captured?' completed':'')+'" style="--legend-color:'+e.color+'"><span class="legend-number">'+(p.captured?'✓ COMPLETADA':j.tracked===e.id?'⌖ SIGUIENDO':'GEN. '+e.generation)+' · '+F.GENERATIONS[e.generation].name.toUpperCase()+'</span><h3>'+esc(e.title)+'</h3><p class="legend-name">'+esc(F.DATA[e.id].name)+' · Nv. '+Math.min(100,e.level+(s.generationJourney.unlocked[e.generation]||0)*8)+'</p><p>'+esc(e.story)+'</p><div class="legend-chips"><span>'+p.clues.filter(Boolean).length+' / 2 pistas</span><span>'+p.medals+' / '+e.badges+' medallas locales</span><span>'+(p.solved?'Prueba resuelta':e.mode==='order'?'Sellos':e.mode==='balance'?'Núcleos':'Laberinto')+'</span></div><small>'+esc(p.reason)+'</small><div class="legend-actions"><button class="secondary" data-legend-detail="'+e.id+'">Ver leyenda</button><button class="secondary" data-legend-track="'+e.id+'" '+(p.captured?'disabled':'')+'>'+(j.tracked===e.id?'Dejar de seguir':'Seguir')+'</button></div></article>';}).join('')||'<p>No hay leyendas con ese nombre en esta región.</p>';for(const b of document.querySelectorAll('[data-legend-detail]'))b.onclick=()=>site({eventId:Number(b.dataset.legendDetail),role:'journal'});for(const b of document.querySelectorAll('[data-legend-track]'))b.onclick=()=>{const id=Number(b.dataset.legendTrack);j.tracked=j.tracked===id?null:id;api.save();renderJournal();};}
function site(o){if(api.battle()||api.locked())return;selected=o;trial=null;renderSite();api.openDialog('legendSiteDialog');}
function addButton(label,fn,primary=false,disabled=false){const b=document.createElement('button');b.className=primary?'primary':'secondary';b.textContent=label;b.disabled=disabled;b.onclick=fn;$('legendSiteActions').append(b);return b;}
function renderSite(){const s=api.state(),e=F.LEGENDS[selected.eventId],p=F.legendStatus(s,e.id);$('legendSiteEyebrow').textContent=(selected.role==='clue'?'INSCRIPCIÓN':selected.role==='shrine'?'SANTUARIO':'DIARIO')+' · '+F.GENERATIONS[e.generation].name;$('legendSiteTitle').textContent=e.title;$('legendSiteCopy').textContent=e.story;$('legendSiteContent').innerHTML='<p class="legend-name">Leyenda de '+esc(F.DATA[e.id].name)+' · '+e.badges+' medallas de '+F.GENERATIONS[e.generation].name+' · encuentro Nv. '+Math.min(100,e.level+(s.generationJourney.unlocked[e.generation]||0)*8)+'</p><div class="legend-objectives">'+e.clueMaps.map((map,i)=>'<article class="'+(p.clues[i]?'done':'')+'"><strong>'+(p.clues[i]?'✓':'◇')+' Pista '+(i+1)+'</strong><span>'+location(s,e.id,'clue',i)+'</span><p>'+esc(p.clues[i]?clueText(s,e,i):'Busca la inscripción en este mapa. Sus coordenadas corresponden a la cuadrícula del juego.')+'</p></article>').join('')+'<article class="'+(p.solved?'done':'')+'"><strong>'+(p.solved?'✓':'✦')+' Santuario</strong><span>'+location(s,e.id,'shrine')+'</span><p>'+esc(p.reason)+'</p></article></div><p class="legend-note">Captura durante el combate: baja sus PS al 20 % o menos, o usa una Master Ball. Si lo debilitas, huyes, pierdes o recargas en combate, sal de la cueva y vuelve a entrar. Las pistas y la prueba se conservan. Cada evento permite una captura por partida.</p>';$('legendSiteActions').innerHTML='';if(selected.role==='clue'&&!p.clues[selected.clue])addButton('Leer inscripción',()=>{if(F.collectLegendClue(s,selected)){api.save();api.refresh();renderSite();api.toast('Pista '+(selected.clue+1)+' registrada · '+e.title);}else api.toast(p.reason);},true,p.medals<e.badges||p.captured);if(F.canLegendRitual(s,e.id)&&!p.solved)addButton('Resolver la prueba',startTrial,true);if(p.ready&&F.canLegendRitual(s,e.id))addButton('Invocar al legendario',async()=>{const enc=F.legendEncounter(api.state(),e.id);if(!enc){api.toast('Acércate al santuario y revisa los requisitos.');return;}$('legendSiteDialog').close();await api.startBattle(enc);},true);if(!p.captured)addButton(F.ensureLegends(s).tracked===e.id?'Dejar de seguir':'Seguir esta leyenda',()=>{const j=F.ensureLegends(s);j.tracked=j.tracked===e.id?null:e.id;api.save();renderSite();});addButton('Volver al diario',()=>{trial=null;renderJournal();api.openDialog('legendsDialog');});}
function startTrial(){const s=api.state(),e=F.LEGENDS[selected.eventId];if(!F.canLegendRitual(s,e.id))return;const q=F.legendPuzzle(s,e.id);trial={id:e.id,q,answer:e.mode==='balance'?[...q.initial]:e.mode==='maze'?[0]:[],message:'Resuelve el ritual usando las inscripciones que encontraste.'};renderTrial();}
function submit(){if(!trial)return;const ok=F.solveLegendRitual(api.state(),trial.id,trial.answer);if(ok){api.save();trial=null;renderSite();api.toast('El santuario respondió. Ya puedes invocar al legendario.');}else{trial.message='El santuario no responde. Revisa las pistas y vuelve a intentarlo.';if(trial.q.mode==='order')trial.answer=[];renderTrial();}}
function moveMaze(next){if(!trial||trial.q.mode!=='maze')return;const last=trial.answer.at(-1);if(trial.q.walls.includes(next)||next<0||next>24||!(Math.abs(last-next)===5||Math.floor(last/5)===Math.floor(next/5)&&Math.abs(last-next)===1)){trial.message='Una runa oscura bloquea ese paso. Busca otro camino.';renderTrial();return;}trial.answer.push(next);if(trial.answer.length>50){trial.answer=[0];trial.message='Regresas al inicio. Busca un recorrido más corto.';}if(next===24){submit();return;}trial.message='El umbral brilla en la esquina inferior derecha.';renderTrial();}
function renderTrial(){const s=api.state(),e=F.LEGENDS[trial.id],q=trial.q,a=trial.answer;$('legendSiteCopy').textContent=trial.message;const hints='<div class="legend-hints"><p>'+esc(clueText(s,e,0))+'</p><p>'+esc(clueText(s,e,1))+'</p></div>';let content='';if(q.mode==='order'){content='<p>Activa los cuatro sellos en el orden que indican las pistas.</p><div class="legend-sequence">'+(a.length?a.map(i=>esc(e.tokens[i])).join(' → '):'El altar espera tu respuesta')+'</div><div class="legend-rune-buttons">'+e.tokens.map((t,i)=>'<button data-legend-rune="'+i+'" '+(a.includes(i)?'disabled':'')+'>'+esc(t)+'</button>').join('')+'</div>';}else if(q.mode==='balance'){content='<p>Ajusta las cargas de cada núcleo. Cada pulsación añade uno: 0 → 1 → 2 → 3 → 4 → 0.</p><div class="legend-core-buttons">'+a.map((v,i)=>'<button data-legend-core="'+i+'"><small>NÚCLEO '+(i+1)+'</small><b>'+v+'</b><span>+1 carga</span></button>').join('')+'</div>';}else{content='<p>Lleva la luz ◉ hasta el umbral ✦. Toca una casilla vecina o usa las flechas.</p><div class="legend-maze" role="group" aria-label="Laberinto de runas de cinco por cinco">'+Array.from({length:25},(_,i)=>'<button data-legend-cell="'+i+'" class="'+(q.walls.includes(i)?'wall':a.at(-1)===i?'current':a.includes(i)?'path':'')+'" aria-label="Fila '+(Math.floor(i/5)+1)+', columna '+(i%5+1)+(q.walls.includes(i)?', bloqueada':'')+'" '+(q.walls.includes(i)?'disabled':'')+'>'+(a.at(-1)===i?'◉':i===24?'✦':q.walls.includes(i)?'■':a.includes(i)?'·':'')+'</button>').join('')+'</div><div class="legend-dpad">'+[[0,'↑'],[1,'→'],[2,'↓'],[3,'←']].map(([i,t])=>'<button data-legend-direction="'+i+'" aria-label="'+['Arriba','Derecha','Abajo','Izquierda'][i]+'">'+t+'</button>').join('')+'</div>';}$('legendSiteContent').innerHTML=hints+content;$('legendSiteActions').innerHTML='';if(q.mode!=='maze')addButton('Comprobar ritual',submit,true,q.mode==='order'&&a.length!==4);addButton('Reiniciar',startTrial);addButton('Volver al santuario',()=>{trial=null;renderSite();});for(const b of document.querySelectorAll('[data-legend-rune]'))b.onclick=()=>{trial.answer.push(Number(b.dataset.legendRune));renderTrial();};for(const b of document.querySelectorAll('[data-legend-core]'))b.onclick=()=>{const i=Number(b.dataset.legendCore);trial.answer[i]=(trial.answer[i]+1)%5;renderTrial();};for(const b of document.querySelectorAll('[data-legend-cell]'))b.onclick=()=>moveMaze(Number(b.dataset.legendCell));for(const b of document.querySelectorAll('[data-legend-direction]'))b.onclick=()=>direction(Number(b.dataset.legendDirection));}
function direction(i){if(!trial||trial.q.mode!=='maze')return;const last=trial.answer.at(-1),next=last+[-5,1,5,-1][i];if(i===1&&last%5===4||i===3&&last%5===0){trial.message='Ese paso sale del laberinto.';renderTrial();return;}moveMaze(next);}
window.addEventListener('keydown',e=>{if(!$('legendSiteDialog').open||!trial||trial.q.mode!=='maze'||e.target.matches('input,textarea,select'))return;const i=['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].indexOf(e.key);if(i>=0){e.preventDefault();direction(i);}});
$('legendGeneration').onchange=()=>{generation=Number($('legendGeneration').value);renderJournal();};$('legendSearch').oninput=renderJournal;$('menuLegendsBtn').onclick=journal;$('legendsClose').onclick=()=>$('legendsDialog').close();$('legendSiteClose').onclick=()=>{trial=null;$('legendSiteDialog').close();};$('legendSiteDialog').addEventListener('close',()=>{trial=null;});
return{journal,site,clueText};
};
window.LegendArt={draw(ctx,o,x,y,time,selected,reducedMotion){const pulse=reducedMotion?0:Math.sin(time*2+o.eventId)*2;ctx.save();ctx.fillStyle='#1b302645';ctx.beginPath();ctx.ellipse(x,y+7,23,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=o.locked?'#738375':o.color;ctx.fillRect(x-19,y-2,38,8);ctx.fillStyle='#455748';ctx.fillRect(x-15,y-7,30,6);ctx.fillStyle='#9ca88b';ctx.fillRect(x-11,y-31,22,25);ctx.fillStyle='#c3c6a6';ctx.fillRect(x-13,y-34,26,5);ctx.fillStyle=o.locked?'#667567':o.color;if(o.role==='shrine'){ctx.fillRect(x-5,y-26,10,10);ctx.fillStyle='#fff4c3';ctx.fillRect(x-2,y-23,4,4);ctx.fillStyle=o.color+'45';ctx.fillRect(x-2,y-58-pulse,4,20);ctx.fillStyle=o.color;ctx.fillRect(x-2,y-65-pulse,4,4);ctx.fillRect(x-5,y-62-pulse,10,2);}else{for(let i=0;i<3;i++)ctx.fillRect(x-7,y-27+i*6,14-i*3,2);}if(selected){ctx.fillStyle='#173a30ed';ctx.fillRect(x-115,y-87,230,18);ctx.fillStyle='#f3e7b6';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(o.role==='shrine'?'SANTUARIO · E PARA INTERACTUAR':'INSCRIPCIÓN · E PARA LEER',x,y-75);}ctx.restore();}};
